const EASY_GROUPS = {};
const STORAGE_KEY = `vstep-shopping-money-template-2026-${MODE}-v1`;

const pages = IS_EASY ? PASSAGES.flatMap(p => (EASY_GROUPS[String(p.id)] || []).map((g, i) => ({
  passageId:p.id, passageTitle:p.title, pageNo:i+1, paragraphIndexes:g.paragraphs, questionNumbers:g.questions
}))) : [];

function newTimer(){ return {remaining:TEST_SECONDS,running:false,lastTick:null}; }
function defaultTimers(){ return Object.fromEntries(PASSAGES.map(p=>[`p${p.id}`,newTimer()])); }
const defaultState = () => ({
  activeIndex:0, answers:{}, checked:{}, showKey:{}, highlights:{}, dictionaryOn:false,
  dictionaryCache:{}, timers:defaultTimers(), fontSize:18
});
let state = defaultState();
let ticker = null;
let currentDictTerm = "";
let dictRequestToken = 0;
const el = {};


document.addEventListener("DOMContentLoaded", init);
function init(){ cacheElements(); loadState(); attachEvents(); applyFontSize(); renderAll(); if(currentTimer().running) startTicker(); }
function cacheElements(){
  ["passageTabs","passageTitle","passageText","questionForm","answeredCount","scoreText","checkBtn","showKeyBtn","resultBox","prevPassageBtn","nextPassageBtn","highlightToggle","clearHighlightsBtn","dictionaryToggle","timerLabel","timerDisplay","startPauseBtn","resetTimerBtn","resetAllBtn","guideBtn","guideDialog","closeGuideBtn","dictPopup","dictCloseBtn","dictMeaning","dictSpeakBtn","workspace","fontDecreaseBtn","fontIncreaseBtn","fontResetBtn","fontSizeDisplay"].forEach(id=>el[id]=document.getElementById(id));
}
function loadState(){
  try{ const raw=localStorage.getItem(STORAGE_KEY); if(raw) state={...defaultState(),...JSON.parse(raw)}; }catch(e){ state=defaultState(); }
  state.activeIndex=Math.trunc(clamp(state.activeIndex,0,PASSAGES.length-1,0));
  state.fontSize=clamp(state.fontSize,16,36,18);
  for(const field of ["answers","checked","showKey","highlights","dictionaryCache","timers"]){ if(!state[field] || typeof state[field]!=="object" || Array.isArray(state[field]))state[field]={}; }
  for(const p of PASSAGES){const k=passageKey(p);if(!state.answers[k]||typeof state.answers[k]!=="object")state.answers[k]={};if(!Array.isArray(state.highlights[k]))state.highlights[k]=[];state.highlights[k]=state.highlights[k].filter(h=>Number.isInteger(h.p)&&p.paragraphs[h.p]&&Number.isInteger(h.start)&&Number.isInteger(h.end)&&h.start>=0&&h.end>h.start&&h.end<=p.paragraphs[h.p].length);}
  state.timers={...defaultTimers(),...(state.timers||{})};
  Object.keys(state.timers).forEach(k=>{ state.timers[k]={...newTimer(),...state.timers[k]};state.timers[k].remaining=clamp(state.timers[k].remaining,0,TEST_SECONDS,TEST_SECONDS);if(!Number.isFinite(state.timers[k].lastTick))state.timers[k].running=false; });
  // Only the active passage timer may keep running after reload. Other passage timers are paused.
  const activeKey=passageKey();
  Object.entries(state.timers).forEach(([k,t])=>{
    if(k!==activeKey){ t.running=false; t.lastTick=null; return; }
    if(t.running && t.lastTick){ const elapsed=Math.max(0,Math.floor((Date.now()-t.lastTick)/1000)); t.remaining=Math.max(0,t.remaining-elapsed); if(t.remaining===0)t.running=false; t.lastTick=t.running?Date.now():null; }
  });
  state.dictionaryCache=state.dictionaryCache||{};
  document.body.classList.toggle("dict-mode",Boolean(state.dictionaryOn));
}
function saveState(){ try{ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }catch(e){} }
function clamp(v,min,max,f){ const n=Number(v); return Number.isFinite(n)?Math.min(max,Math.max(min,n)):f; }
function activePassage(){ return IS_EASY ? PASSAGES.find(p=>p.id===pages[state.activeIndex].passageId) : PASSAGES[state.activeIndex]; }
function activePage(){ return IS_EASY ? pages[state.activeIndex] : null; }
function passageKey(p=activePassage()){ return `p${p.id}`; }
function checkKey(){ if(!IS_EASY) return passageKey(); const pg=activePage(); return `p${pg.passageId}-page-${pg.pageNo}`; }
function questionsForView(){ const p=activePassage(); if(!IS_EASY) return p.questions; const nums=new Set(activePage().questionNumbers); return p.questions.filter(q=>nums.has(q.n)); }
function paragraphsForView(){ const p=activePassage(); if(!IS_EASY) return p.paragraphs.map((text,i)=>({i,text})); return activePage().paragraphIndexes.map(i=>({i,text:p.paragraphs[i]})); }
function globalQuestionNumber(passage,qOrN){ const n=typeof qOrN==="number"?qOrN:qOrN.n; return n; }
function questionColor(globalNo){ const hue=Math.round((globalNo*137.508)%360); return `hsl(${hue} 78% 84%)`; }
function currentTimer(p=activePassage()){ const k=passageKey(p); state.timers[k]=state.timers[k]||newTimer(); return state.timers[k]; }
function renderAll(){ renderTabs(); renderPassage(); renderQuestions(); updateProgress(); updateNav(); updateTimer(); updateToolLabels(); renderResult(); }

function renderTabs(){
  if(IS_EASY){ el.passageTabs.innerHTML=pages.map((pg,i)=>{ const label=`${pg.passageId}.${pg.pageNo}`; const key=`p${pg.passageId}-page-${pg.pageNo}`; const qs=PASSAGES.find(p=>p.id===pg.passageId).questions.filter(q=>pg.questionNumbers.includes(q.n)); const score=state.checked[key]?` • ${getScore(qs,`p${pg.passageId}`)}/${qs.length}`:""; return `<button class="tab-btn ${i===state.activeIndex?'active':''}" data-index="${i}" type="button">${label}${score}</button>`; }).join("");
  } else {
    el.passageTabs.innerHTML=PASSAGES.map((p,i)=>{ const k=`p${p.id}`; const score=state.checked[k]?` • ${getScore(p.questions,k)}/${p.questions.length}`:""; return `<button class="tab-btn ${i===state.activeIndex?'active':''}" data-index="${i}" aria-current="${i===state.activeIndex?"page":"false"}" type="button">Passage ${p.id}${score}</button>`; }).join("");
  }
}
function renderPassage(){
  const p=activePassage(), pg=activePage();
  el.passageTitle.textContent = IS_EASY ? `${p.title} — Page ${pg.pageNo}` : p.title;
  const showKey = IS_TEACHER && Boolean(state.showKey[passageKey(p)]);
  const html = paragraphsForView().map(({i,text})=>`<div class="passage-paragraph"><div class="paragraph-number">P${i+1}</div><div class="paragraph-content" data-paragraph-index="${i}">${renderAnnotated(text,i,p,showKey)}</div></div>`).join("");
  el.passageText.innerHTML = html;
}
function wordIntervals(text){
  const out=[]; const re=/[A-Za-z]+(?:[-’'][A-Za-z]+)*/g; let m;
  while((m=re.exec(text))) out.push({start:m.index,end:m.index+m[0].length,kind:"dict",term:m[0]});
  return out;
}
function renderAnnotated(text, paragraphIndex, passage, showKey){
  const intervals=[];
  passage.references.filter(r=>r.p===paragraphIndex).forEach(r=>intervals.push({start:r.start,end:r.end,kind:"reference"}));
  wordIntervals(text).forEach(r=>intervals.push(r));
  const manual=(state.highlights[passageKey(passage)]||[]).filter(h=>h.p===paragraphIndex); manual.forEach(h=>intervals.push({start:h.start,end:h.end,kind:"manual"}));
  if(showKey){ passage.questions.forEach(q=>{ const gq=globalQuestionNumber(passage,q); q.evidencePhrases.forEach(ep=>{ if(ep.p===paragraphIndex){if(Number.isInteger(ep.start))intervals.push({start:ep.start,end:ep.end,kind:"evidence",q:gq});else addTermIntervals(intervals,text,ep.text,{kind:"evidence",q:gq});} }); }); }
  const boundaries=new Set([0,text.length]); intervals.forEach(r=>{boundaries.add(r.start);boundaries.add(r.end)}); const pts=[...boundaries].sort((a,b)=>a-b);
  let out="";
  for(let x=0;x<pts.length-1;x++){
    const a=pts[x],b=pts[x+1]; if(a===b)continue; const seg=text.slice(a,b); const active=intervals.filter(r=>r.start<=a && r.end>=b);
    const classes=["annot-segment"]; let attrs="";
    if(active.some(r=>r.kind==="manual"))classes.push("manual-highlight");
    if(active.some(r=>r.kind==="reference"))classes.push("reference-term");
    const dictRange=active.find(r=>r.kind==="dict"); if(dictRange){classes.push("dict-hit"); attrs+=` data-dict-word="${escapeAttr(dictRange.term)}"`;}
    const evid=active.filter(r=>r.kind==="evidence").sort((u,v)=>u.q-v.q);
    if(evid.length){ const q=evid[0].q; classes.push("evidence-segment"); attrs+=` style="--evidence-color:${questionColor(q)}"`; const ending=evid.filter(r=>r.end===b).map(r=>r.q); if(ending.length){classes.push("evidence-end");attrs+=` data-evidence-label="${escapeAttr(ending.map(n=>'Q'+n).join('/'))}"`;} }
    out+=`<span class="${classes.join(' ')}"${attrs}>${escapeHtml(seg)}</span>`;
  }
  return out;
}
function addTermIntervals(arr,text,term,meta){
  const low=text.toLowerCase(),needle=term.toLowerCase();let from=0;
  while(true){const i=low.indexOf(needle,from);if(i<0)break;const before=i>0?low[i-1]:"",after=i+needle.length<low.length?low[i+needle.length]:"";const okBefore=!before||!/[a-z0-9]/i.test(before),okAfter=!after||!/[a-z0-9]/i.test(after);if(okBefore&&okAfter)arr.push({start:i,end:i+needle.length,...meta});from=i+Math.max(1,needle.length);}
}
function wrapDictionaryWords(text){
  const s=String(text), re=/[A-Za-z]+(?:[-’'][A-Za-z]+)*/g; let out="",last=0,m;
  while((m=re.exec(s))){ out+=escapeHtml(s.slice(last,m.index)); out+=`<span class="dict-hit" data-dict-word="${escapeAttr(m[0])}">${escapeHtml(m[0])}</span>`; last=m.index+m[0].length; }
  return out+escapeHtml(s.slice(last));
}
function renderQuestions(){
  const p=activePassage(),qs=questionsForView(),answers=state.answers[passageKey(p)]||{},checked=Boolean(state.checked[checkKey()]),showKey=IS_TEACHER&&Boolean(state.showKey[passageKey(p)]);
  let previousSection="";
  el.questionForm.innerHTML=qs.map(q=>{
    const gq=globalQuestionNumber(p,q), chosen=answers[q.n]||"";
    const sectionHeading=q.section!==previousSection?`<div class="question-section-heading">${escapeHtml(q.section)}</div>`:""; previousSection=q.section;
    const options=Object.entries(q.options).map(([letter,text])=>{const cls=["option-row"];if(checked&&chosen===letter)cls.push(letter===q.answer?"selected-correct":"selected-wrong");if(showKey&&letter===q.answer)cls.push("correct-key");return `<label class="${cls.join(' ')}"><input type="radio" name="q${q.n}" value="${letter}" ${chosen===letter?'checked':''}><span class="option-letter">${letter}.</span><span>${wrapDictionaryWords(text)}</span></label>`;}).join("");
    let feedback="";if(checked){if(!chosen)feedback=`<div class="check-feedback unanswered">Not answered.</div>`;else if(chosen===q.answer)feedback=`<div class="check-feedback correct">✓ Correct</div>`;else feedback=`<div class="check-feedback wrong">✗ Incorrect</div>`;}
    const evidence=showKey?(q.section==="B2 Paraphrase Challenge"?`<div class="evidence-box"><strong>Answer: ${q.answer}</strong><div class="paraphrase-correct">${wrapDictionaryWords(q.evidenceExplanation)}</div></div>`:`<div class="evidence-box"><strong>Answer: ${q.answer}</strong><div class="evidence-source"><strong>Evidence:</strong> ${wrapDictionaryWords(q.evidenceExplanation)}</div><div class="vi-explanation" lang="vi"><strong>Giải thích tiếng Việt:</strong> ${escapeHtml(q.viExplanation||"")}</div></div>`):"";
    const qLabel=q.section==="B2 Paraphrase Challenge"?`P${q.displayN}`:`${q.displayN}`;
    return `${sectionHeading}<section class="question-card" style="--q-color:${questionColor(gq)}"><div class="question-meta"><span class="question-number">${qLabel}</span>${""}</div><p class="question-text">${wrapDictionaryWords(q.text)}</p>${options}${feedback}${evidence}</section>`;
  }).join("");
}
function attachEvents(){
  el.fontDecreaseBtn.addEventListener("click",()=>setFontSize(state.fontSize-2));
  el.fontIncreaseBtn.addEventListener("click",()=>setFontSize(state.fontSize+2));
  el.fontResetBtn.addEventListener("click",()=>setFontSize(18));
  el.passageTabs.addEventListener("keydown",e=>{if(!["ArrowLeft","ArrowRight","Home","End"].includes(e.key))return;e.preventDefault();const next=e.key==="Home"?0:e.key==="End"?PASSAGES.length-1:(state.activeIndex+(e.key==="ArrowRight"?1:-1)+PASSAGES.length)%PASSAGES.length;goToIndex(next);el.passageTabs.querySelector(`[data-index="${next}"]`)?.focus();});
  el.passageTabs.addEventListener("click",e=>{const b=e.target.closest("[data-index]");if(!b)return;goToIndex(Number(b.dataset.index));});
  el.questionForm.addEventListener("change",e=>{if(e.target.type!=="radio")return;const p=activePassage(),k=passageKey(p),qn=Number(e.target.name.slice(1));state.answers[k]=state.answers[k]||{};state.answers[k][qn]=e.target.value;state.checked[checkKey()]=false;saveState();renderQuestions();renderTabs();updateProgress();renderResult();const replacement=el.questionForm.querySelector(`input[name="q${qn}"][value="${e.target.value}"]`);if(replacement)replacement.focus({preventScroll:true});});
  el.checkBtn.addEventListener("click",()=>{state.checked[checkKey()]=true;saveState();renderQuestions();renderTabs();updateProgress();renderResult();scrollToIssue();});
  if(el.showKeyBtn)el.showKeyBtn.addEventListener("click",()=>{const k=passageKey();state.showKey[k]=!state.showKey[k];saveState();renderPassage();renderQuestions();updateToolLabels();renderResult();});
  el.highlightToggle.addEventListener("click",()=>{document.body.classList.toggle("highlight-mode");updateToolLabels();});
  el.clearHighlightsBtn.addEventListener("click",()=>{state.highlights[passageKey()]=[];saveState();renderPassage();});
  el.passageText.addEventListener("mouseup",handleSelectionHighlight); el.passageText.addEventListener("touchend",()=>setTimeout(handleSelectionHighlight,30));
  el.dictionaryToggle.addEventListener("click",()=>{state.dictionaryOn=!state.dictionaryOn;document.body.classList.toggle("dict-mode",state.dictionaryOn);if(!state.dictionaryOn)closeDict();saveState();updateToolLabels();});
  el.workspace.addEventListener("click",e=>{if(!state.dictionaryOn)return;const t=e.target.closest("[data-dict-word]");if(!t)return;e.preventDefault();e.stopPropagation();openDict(t.dataset.dictWord,t.getBoundingClientRect());},true);
  el.dictCloseBtn.addEventListener("click",closeDict);el.dictSpeakBtn.addEventListener("click",speakCurrent);document.addEventListener("keydown",e=>{if(e.key==="Escape")closeDict();});
  el.startPauseBtn.addEventListener("click",toggleTimer);el.resetTimerBtn.addEventListener("click",resetTimer);
  el.prevPassageBtn.addEventListener("click",()=>changeIndex(-1));el.nextPassageBtn.addEventListener("click",()=>changeIndex(1));
  el.resetAllBtn.addEventListener("click",()=>{if(!confirm("Reset all answers, checks, evidence, highlights, dictionary mode, and all passage timers?"))return;stopTicker();state=defaultState();try{localStorage.removeItem(STORAGE_KEY);}catch(e){}applyFontSize();document.body.classList.remove("dict-mode","highlight-mode");closeDict();renderAll();});
  el.guideBtn.addEventListener("click",()=>{if(typeof el.guideDialog.showModal==="function")el.guideDialog.showModal();});el.closeGuideBtn.addEventListener("click",()=>el.guideDialog.close());
}
function handleSelectionHighlight(){
  if(!document.body.classList.contains("highlight-mode"))return;const sel=window.getSelection();if(!sel||sel.isCollapsed||sel.rangeCount===0)return;const range=sel.getRangeAt(0),startBox=getParagraphContainer(range.startContainer),endBox=getParagraphContainer(range.endContainer);if(!startBox||!endBox||startBox!==endBox){sel.removeAllRanges();return;}
  const pIndex=Number(startBox.dataset.paragraphIndex);let start=getTextOffset(startBox,range.startContainer,range.startOffset),end=getTextOffset(startBox,range.endContainer,range.endOffset);if(start>end)[start,end]=[end,start];if(end-start<1){sel.removeAllRanges();return;}
  const k=passageKey();state.highlights[k]=state.highlights[k]||[];state.highlights[k].push({p:pIndex,start,end});state.highlights[k]=mergeRanges(state.highlights[k]);saveState();sel.removeAllRanges();renderPassage();
}
function getParagraphContainer(node){const e=node.nodeType===1?node:node.parentElement;return e?.closest?.(".paragraph-content")||null;}
function getTextOffset(container,node,offset){let total=0,found=false;const walker=document.createTreeWalker(container,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const n=walker.currentNode;if(n===node){total+=offset;found=true;break;}total+=n.nodeValue.length;}return found?total:0;}
function mergeRanges(items){const byP={};items.forEach(h=>(byP[h.p]??=[]).push({...h}));const out=[];Object.entries(byP).forEach(([p,arr])=>{arr.sort((a,b)=>a.start-b.start);let cur=null;arr.forEach(h=>{if(!cur)cur={...h};else if(h.start<=cur.end)cur.end=Math.max(cur.end,h.end);else{out.push(cur);cur={...h};}});if(cur)out.push(cur);});return out;}

function normalizeLookupWord(term){
  let w=String(term).trim().replace(/’/g,"'").toLowerCase();
  w=w.replace(/^['-]+|['-]+$/g,""); if(w.endsWith("'s"))w=w.slice(0,-2); return w;
}
function localDictionaryEntry(term){
  const key=normalizeLookupWord(term); const entry=WORK_DICTIONARY[key]; if(entry && !entry.term.includes(" "))return entry; return null;
}
async function openDict(term,rect){
  const token=++dictRequestToken,currentTerm=String(term);currentDictTerm=currentTerm;positionDict(rect);el.dictPopup.hidden=false;el.dictMeaning.textContent="Đang tra nghĩa…";el.dictSpeakBtn.disabled=false;
  const local=localDictionaryEntry(currentTerm);if(local){el.dictMeaning.textContent=local.meaning;return;}
  const key=normalizeLookupWord(currentTerm),cached=state.dictionaryCache[key];
  if(cached){if(token!==dictRequestToken)return;el.dictMeaning.textContent=typeof cached==="string"?cached:(cached.meaning||"");return;}
  let meaning="";try{meaning=await fetchVietnameseMeaning(key);}catch(e){}if(token!==dictRequestToken)return;
  const finalMeaning=meaning||"Không tìm thấy nghĩa tiếng Việt lúc này.";if(meaning){state.dictionaryCache[key]={meaning};saveState();}el.dictMeaning.textContent=finalMeaning;
}
function positionDict(rect){const margin=12,w=Math.min(300,window.innerWidth-2*margin);let left=Math.max(margin,Math.min(window.innerWidth-w-margin,rect.left)),top=rect.bottom+8;if(top+190>window.innerHeight)top=Math.max(margin,rect.top-185);el.dictPopup.style.left=`${left}px`;el.dictPopup.style.top=`${top}px`;}
async function fetchWithTimeout(url,ms=6000){const controller=new AbortController(),id=setTimeout(()=>controller.abort(),ms);try{return await fetch(url,{signal:controller.signal});}finally{clearTimeout(id);}}
async function fetchVietnameseMeaning(word){
  if(!word)return "";const url=`https://api.mymemory.translated.net/get?q=${encodeURIComponent(word)}&langpair=en%7Cvi`;const r=await fetchWithTimeout(url);if(!r.ok)return "";const data=await r.json();const t=String(data?.responseData?.translatedText||"").trim();return t&&t.toLowerCase()!==word.toLowerCase()?t:"";
}
function closeDict(){if(el.dictPopup)el.dictPopup.hidden=true;currentDictTerm="";dictRequestToken++;}
function speakCurrent(){if(!currentDictTerm||!("speechSynthesis" in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(currentDictTerm);u.lang="en-US";u.rate=.85;window.speechSynthesis.speak(u);}

function toggleTimer(){const t=currentTimer();if(t.remaining<=0)return;if(t.running){pauseTimer(activePassage().id);}else{pauseOtherTimers(activePassage().id);t.running=true;t.lastTick=Date.now();saveState();startTicker();}updateTimer();}
function resetTimer(){stopTicker();const k=passageKey();state.timers[k]=newTimer();saveState();updateTimer();}
function pauseOtherTimers(keepId){PASSAGES.forEach(p=>{if(p.id!==keepId)pauseTimer(p.id,false);});}
function pauseTimer(passageId,shouldSave=true){const k=`p${passageId}`,t=state.timers[k];if(!t)return;if(t.running&&t.lastTick){const elapsed=Math.max(0,Math.floor((Date.now()-t.lastTick)/1000));t.remaining=Math.max(0,t.remaining-elapsed);}t.running=false;t.lastTick=null;if(shouldSave)saveState();if(activePassage().id===passageId)stopTicker();}
function startTicker(){stopTicker();ticker=setInterval(()=>{const t=currentTimer();if(!t.running)return;const now=Date.now(),elapsed=Math.max(0,Math.floor((now-(t.lastTick||now))/1000));if(elapsed===0)return;t.lastTick=(t.lastTick||now)+elapsed*1000;t.remaining=Math.max(0,t.remaining-elapsed);if(t.remaining===0){t.running=false;t.lastTick=null;stopTicker();}saveState();updateTimer();},1000);}
function stopTicker(){if(ticker){clearInterval(ticker);ticker=null;}}
function updateTimer(){const t=currentTimer(),m=String(Math.floor(t.remaining/60)).padStart(2,"0"),s=String(t.remaining%60).padStart(2,"0");el.timerLabel.textContent=`Passage ${activePassage().id} timer`;el.timerDisplay.textContent=`${m}:${s}`;const action=t.running?"Pause timer":(t.remaining===0?"Time up":"Start timer");el.startPauseBtn.textContent=t.running?"Ⅱ":"▶";el.startPauseBtn.setAttribute("aria-label",action);el.startPauseBtn.title=action;el.startPauseBtn.disabled=t.remaining===0;const card=el.timerDisplay.closest(".timer-card");card.classList.toggle("timer-warning",t.remaining<=300&&t.remaining>60);card.classList.toggle("timer-danger",t.remaining<=60);}
function targetPassageId(index){return IS_EASY?pages[index].passageId:PASSAGES[index].id;}
function goToIndex(index){const max=IS_EASY?pages.length:PASSAGES.length;if(index<0||index>=max||index===state.activeIndex)return;const oldId=activePassage().id,newId=targetPassageId(index);if(oldId!==newId)pauseTimer(oldId);state.activeIndex=index;document.querySelector(".reading-pane").scrollTop=0;document.querySelector(".question-pane").scrollTop=0;closeDict();saveState();renderAll();if(currentTimer().running)startTicker();else stopTicker();}
function changeIndex(d){goToIndex(state.activeIndex+d);}
function updateNav(){const max=IS_EASY?pages.length:PASSAGES.length;el.prevPassageBtn.disabled=state.activeIndex===0;el.nextPassageBtn.disabled=state.activeIndex===max-1;el.prevPassageBtn.textContent=IS_EASY?"← Previous page":"← Previous passage";el.nextPassageBtn.textContent=IS_EASY?"Next page →":"Next passage →";}
function updateProgress(){const qs=questionsForView(),ans=state.answers[passageKey()]||{},done=qs.filter(q=>ans[q.n]).length;el.answeredCount.textContent=`${done}/${qs.length} answered`;el.scoreText.textContent=state.checked[checkKey()]?`Score: ${getScore(qs)}/${qs.length}`:"Score: --";}
function getScore(qs,key=passageKey()){const ans=state.answers[key]||{};return qs.reduce((n,q)=>n+(ans[q.n]===q.answer?1:0),0);}
function renderResult(){const p=activePassage(),qs=questionsForView();if(!state.checked[checkKey()]&&!(IS_TEACHER&&state.showKey[passageKey()])){el.resultBox.hidden=true;return;}el.resultBox.hidden=false;let msg=state.checked[checkKey()]?`Checked: <strong>${getScore(qs)}/${qs.length}</strong>.`:"";if(IS_TEACHER&&state.showKey[passageKey()])msg+=` Answer key: <strong>${qs.map(q=>(q.section==='B2 Paraphrase Challenge'?'P'+q.displayN:q.displayN)+'.'+q.answer).join(' · ')}</strong>. Evidence is highlighted in matching question colors.`;el.resultBox.innerHTML=msg;}
function updateToolLabels(){const h=document.body.classList.contains("highlight-mode");el.highlightToggle.classList.toggle("active",h);el.highlightToggle.setAttribute("aria-label",h?"Highlight on":"Highlight off");el.highlightToggle.setAttribute("aria-pressed",String(h));el.dictionaryToggle.setAttribute("aria-pressed",String(Boolean(state.dictionaryOn)));el.highlightToggle.title=h?"Highlight: On":"Highlight: Off";el.dictionaryToggle.classList.toggle("active",Boolean(state.dictionaryOn));el.dictionaryToggle.setAttribute("aria-label",state.dictionaryOn?"Dictionary on":"Dictionary off");el.dictionaryToggle.title=state.dictionaryOn?"Dictionary: On":"Dictionary: Off";if(el.showKeyBtn){const on=Boolean(state.showKey[passageKey()]);el.showKeyBtn.textContent=on?"Hide answer key & evidence":"Show answer key & evidence";}}
function scrollToIssue(){const x=el.questionForm.querySelector(".check-feedback.wrong,.check-feedback.unanswered");if(x)x.scrollIntoView({behavior:"smooth",block:"center"});}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
function escapeAttr(v){return escapeHtml(v);}

function setFontSize(value){state.fontSize=clamp(value,16,36,18);applyFontSize();saveState();}
function applyFontSize(){const size=clamp(state.fontSize,16,36,18);document.documentElement.style.setProperty("--font-size-reading",`${size/16}rem`);document.documentElement.style.setProperty("--font-size-question",`${size/16}rem`);el.fontSizeDisplay.textContent=`${size}`;el.fontDecreaseBtn.disabled=size<=16;el.fontIncreaseBtn.disabled=size>=36;}
